/* ---- exact DFS ---- */
static int ord[MX], comp[MX]; /* edge order; comp[i]= vertex completed when edge ord[i] assigned (-1 none) */
static int usedL[2*MX+1], usedS[2*MX+1], psum[MX], rem[MX]; static long long nodes;
static int dfs(int i){
  nodes++;
  if(i==Q){ /* root completes */ if(counting>=0){ totcount++; return 0;} return 1; }
  int e=ord[i];
  for(int L=-K; L<=K; L++){ if(!L||usedL[L+MX]) continue;
    if(i==0 && L<0 && counting<0) continue; /* global negation symmetry */
    int u=eu[e],v=ev[e];
    psum[u]+=L; psum[v]+=L; rem[u]--; rem[v]--;
    int ok=1, done[2]={-1,-1}, nd=0;
    int ww[2]={u,v};
    for(int t=0;t<2;t++){int w=ww[t]; if(rem[w]==0){ int s=psum[w]; if(s<-K||s>K||usedS[s+MX]) {ok=0;} else {usedS[s+MX]=1; done[nd++]=w;} } if(!ok) break;}
    if(ok){ usedL[L+MX]=1; lab[e]=L; int r=dfs(i+1); usedL[L+MX]=0; if(r){ for(int t=0;t<nd;t++) usedS[psum[done[t]]+MX]=0; psum[u]-=L; psum[v]-=L; rem[u]++; rem[v]++; return 1;} }
    for(int t=0;t<nd;t++) usedS[psum[done[t]]+MX]=0;
    psum[u]-=L; psum[v]-=L; rem[u]++; rem[v]++;
  }
  return 0;
}
static void setup_order(int *vpar){
  /* gentreeg: vertices 1..n, parent vpar[j]<j for j>=2. Edge j-2 = (j-1, vpar[j]-1). Order: decreasing j (children before parents) */
  int i=0; for(int j=P;j>=2;j--) ord[i++]=j-2;
}
static int exact(int *vpar){
  setup_order(vpar);
  memset(usedL,0,sizeof usedL); memset(usedS,0,sizeof usedS);
  for(int v=0;v<P;v++){psum[v]=0; rem[v]=deg[v];}
  nodes=0; int r=dfs(0); if(nodes>nodes_max) nodes_max=nodes; return r;
}
static FILE *hardf=NULL;
void segproc(FILE *f, int *vpar, int n){
  P=n; K=(n-1)/2; Q=n-1; ntrees++;
  for(int v=0;v<n;v++) deg[v]=0;
  for(int j=2;j<=n;j++){int e=j-2; eu[e]=j-1; ev[e]=vpar[j]-1; inc[eu[e]][deg[eu[e]]++]=e; inc[ev[e]][deg[ev[e]]++]=e;}
  NI=0; for(int v=0;v<n;v++) if(deg[v]>1) intv[NI++]=v;
  if(reduce_){ /* twin-leaf lemma: a vertex with >=2 leaf neighbours => SEG from the order p-2 tree */
    int lc[MX]={0}; for(int e=0;e<Q;e++){ if(deg[eu[e]]==1) lc[ev[e]]++; if(deg[ev[e]]==1) lc[eu[e]]++; }
    for(int v=0;v<n;v++) if(lc[v]>=2){ nskip++; return; } }
  if(counting>=0){ totcount=0; exact(vpar); if(mincount<0||totcount<mincount) mincount=totcount;
     if(counting>0){ printf("%lld", totcount); for(int j=2;j<=n;j++) printf(" %d",vpar[j]); printf("\n"); } return; }
  if(dfsfirst){ int ok=exact(vpar); ndfs++; if(ok&&!verify()){fprintf(stderr,"VERIFYFAIL DFS\n"); exit(2);} if(!ok){nfail++; fprintf(stderr,"NOSEG n=%d:",n); for(int j=2;j<=n;j++) fprintf(stderr," %d",vpar[j]); fprintf(stderr,"\n");} return; }
  int tries;
  for(tries=0;tries<4;tries++){ if(localsearch(200000LL<<(2*tries))) break; }
  int ok;
  if(tries<4){ nls++; hist[tries]++; ok=verify(); if(!ok){fprintf(stderr,"VERIFYFAIL LS\n"); exit(2);} }
  else { ndfs++; ok=exact(vpar); 
     if(ok){ if(!verify()){fprintf(stderr,"VERIFYFAIL DFS\n"); exit(2);} }
     if(hardf){ fprintf(hardf,"%d %lld",ok,nodes); for(int j=2;j<=n;j++) fprintf(hardf," %d",vpar[j]); fputc('\n',hardf);} }
  if(!ok){ nfail++; fprintf(stderr,"NOSEG n=%d:",n); for(int j=2;j<=n;j++) fprintf(stderr," %d",vpar[j]); fprintf(stderr,"\n"); }
}
extern int gmain(int,char**); static void report(void);
int main(int argc,char**argv){
  char *m=getenv("MODE"); if(m&&!strcmp(m,"count")) counting=0; if(m&&!strcmp(m,"countall")) counting=1;
  if(m&&!strcmp(m,"dfs")) dfsfirst=1;
  if(getenv("REDUCE")) reduce_=1;
  char *nz=getenv("NOISE"); if(nz) NOISE=atoi(nz);
  char *h=getenv("HARD"); if(h) hardf=fopen(h,"w");
  char *s=getenv("SEED"); if(s) rng ^= strtoull(s,0,10)*0x9E3779B97F4A7C15ULL;
  atexit(report);
  int r=gmain(argc,argv);
  return r;
}
static void report(void){
  if(counting>=0) fprintf(stderr,"RESULT trees=%lld mincount=%lld\n",ntrees,mincount);
  else fprintf(stderr,"RESULT trees=%lld ls=%lld dfs=%lld fail=%lld maxnodes=%lld h=%lld,%lld,%lld,%lld lsit=%lld skip=%lld\n",ntrees,nls,ndfs,nfail,nodes_max,hist[0],hist[1],hist[2],hist[3],lsiters,nskip);
  if(hardf) fclose(hardf);
}
