def _groups(recording: dict[str, Any]) -> dict[str, list[dict[str, Any]]]:
    groups: dict[str, list[dict[str, Any]]] = {key: [] for key in MODALITIES}
    for event in recording["events"]:
        # A zero-length edit carries no behavioral text evidence.
        if event["type"] == "text" and sum(_counts(event)) == 0:
            continue
        groups[event["type"]].append(event)
    return groups


def _moving_segments(events: list[dict[str, Any]]) -> list[tuple[float, float, float]]:
    result = []
    for left, right in zip(events, events[1:]):
        dt = right["t_ms"] - left["t_ms"]
        dx, dy = right["x"] - left["x"], right["y"] - left["y"]
        if dt > 0 and math.hypot(dx, dy) > 0:
            result.append((dx, dy, float(dt)))
    return result


def _evidence_from_groups(groups: dict[str, list[dict[str, Any]]]) -> list[str]:
    reasons = []
    for modality, events in groups.items():
        if len(events) < MIN_EVENTS[modality]:
            reasons.append(
                f"{modality}: need at least {MIN_EVENTS[modality]} meaningful "
                f"events; found {len(events)}"
            )
        elif len(_intervals(events)) < MIN_POSITIVE_INTERVALS[modality]:
            reasons.append(
                f"{modality}: need at least {MIN_POSITIVE_INTERVALS[modality]} "
                "positive intervals"
            )
    if len(groups["pointer"]) >= MIN_EVENTS["pointer"]:
        if len(_moving_segments(groups["pointer"])) < 10:
            reasons.append("pointer: need at least 10 nonzero, positive-time movements")
    return reasons


def evidence_issues(recording: dict[str, Any]) -> list[str]:
    """Describe insufficient evidence; missing evidence is never a match."""
    validate_recording(recording)
    return _evidence_from_groups(_groups(recording))


def _lag1(values: list[float]) -> float:
    if len(values) < 3:
        return 0.0
    left, right = values[:-1], values[1:]
    left_mean, right_mean = mean(left), mean(right)
    left_dev = [value - left_mean for value in left]
    right_dev = [value - right_mean for value in right]
    denominator = math.sqrt(sum(x * x for x in left_dev) * sum(x * x for x in right_dev))
    if denominator == 0:
        return 0.0
    return max(-1.0, min(1.0, sum(x * y for x, y in zip(left_dev, right_dev)) / denominator))


def _spread(values: list[float]) -> float:
    average = mean(values)
    return math.log1p(pstdev(values) / average) if average > 0 else 0.0


def _local_change(values: list[float]) -> float:
    # Subtract logs rather than dividing first: valid subnormal movement lengths
    # can otherwise overflow a ratio despite both operands being finite.
    changes = [abs(math.log(right) - math.log(left)) for left, right in zip(values, values[1:]) if left > 0 and right > 0]
    return median(changes) if changes else 0.0


def _sequence_features(prefix: str, values: list[float]) -> dict[str, float]:
    return {
        f"{prefix}.spread": _spread(values),
        f"{prefix}.lag1": _lag1(values),
        f"{prefix}.local_change": _local_change(values),
    }


def extract_features(recording: dict[str, Any]) -> dict[str, float]:
    """Return behavioral features for each sufficiently represented modality.

    Partial vectors are useful diagnostically; ``score_recording`` explicitly
    refuses a positive decision if any required modality is insufficient.
    Text origin and click button are validated format fields, not features.
    """
    validate_recording(recording)
    groups = _groups(recording)
    result: dict[str, float] = {}
    for modality, events in groups.items():
        intervals = _intervals(events)
        if len(events) < MIN_EVENTS[modality] or len(intervals) < MIN_POSITIVE_INTERVALS[modality]:
            continue
        if modality == "pointer" and len(_moving_segments(events)) < 10:
            continue
        result.update(_sequence_features(f"{modality}.interval", intervals))
        if modality == "pointer":
            segments = _moving_segments(events)
            lengths = [math.hypot(dx, dy) for dx, dy, _ in segments]
            speeds = [length / segment[2] for length, segment in zip(lengths, segments)]
            result.update(_sequence_features("pointer.step", lengths))
            result.update(_sequence_features("pointer.speed", speeds))
            turns = [
                math.atan2(first[0] * second[1] - first[1] * second[0], first[0] * second[0] + first[1] * second[1]) / math.pi
                for first, second in zip(segments, segments[1:])
            ]
            abs_turns = [abs(value) for value in turns]
            result["pointer.turn.mean_abs"] = mean(abs_turns)
            result["pointer.turn.std_abs"] = pstdev(abs_turns)
            result["pointer.turn.lag1"] = _lag1(turns)
            result["pointer.turn.reversal_fraction"] = mean(float(value > 0.5) for value in abs_turns)
            result["pointer.turn.direction_changes"] = mean(
                float(left * right < 0) for left, right in zip(turns, turns[1:])
            )
        elif modality == "text":
            counts = [_counts(event) for event in events]
            bursts = [float(inserted) for inserted, _ in counts if inserted > 0]
            corrections = [event["action"] != "insert" or removed > 0 for event, (_, removed) in zip(events, counts)]
            result["text.burst.log_median"] = math.log1p(median(bursts)) if bursts else 0.0
            result["text.burst.spread"] = _spread(bursts) if bursts else 0.0
            result["text.correction.fraction"] = mean(float(value) for value in corrections)
            total = sum(inserted + removed for inserted, removed in counts)
            result["text.correction.removed_fraction"] = sum(removed for _, removed in counts) / total
            correction_gaps, other_gaps = [], []
            for index in range(1, len(events)):
                dt = events[index]["t_ms"] - events[index - 1]["t_ms"]
                if dt > 0:
                    (correction_gaps if corrections[index] else other_gaps).append(dt)
            result["text.correction.pause_logratio"] = (
                math.log(median(correction_gaps) / median(other_gaps))
                if correction_gaps and other_gaps else 0.0
            )
    if any(not math.isfinite(value) for value in result.values()):
        raise RecordingError("Feature extraction produced a non-finite value")
    return dict(sorted(result.items()))


def feature_floor(name: str) -> float:
    """Fixed, pre-evaluation regularization of small enrollment dispersions.

    Ratios/correlations are dimensionless. Floors prevent a constant training
    column or a small sample from implying infinite confidence. They are an
    engineering choice for this prototype, not empirically validated constants.
    """
    if name.endswith(".lag1"):
        return 0.12
    if name.endswith("pause_logratio") or name.endswith("log_median"):
        return 0.18
    if name.endswith("local_change") or name.endswith(".spread"):
        return 0.10
    return 0.06

